#define SIN(x) (.5+.5*sin(x))
#define N 6.
#define K 1.1
#define PI 3.141592 

mat2 rot(float a) {float s=sin(a), c=cos(a); return mat2(c, s, -s, c);}

// by Nusan
float curve(float t, float d) {
  t/=d;
  return mix(floor(t), floor(t)+1., pow(smoothstep(0.,1.,fract(t)), 10.));
}

vec3 pal(float t) {

    vec3 a = vec3(.6);
    vec3 b = vec3(1.);
    vec3 c = vec3(.5);
    vec3 d = vec3(0.149,0.875,0.729);

    return a + b*cos(6.283*(c*t+d));
}

// chebyshev distance
float chebd(vec2 v, float k) {
    return pow(pow(abs(v.x), k)+pow(abs(v.y), k), 1./k);
}


 float flower(vec2 uv) {
    float n = 3.;
    float a = atan(uv.y,uv.x);

    float d = length( uv) - cos(a*n);
    return smoothstep(fwidth(d), 0., abs(d));    
}
#define PI 3.141592
#define TAU 2.*PI
#define hue(v) ( .6 + .6 * cos( 6.3*(v) + vec3(0,23,21) ) )
#define rot(a) mat2(cos(a), sin(a), -sin(a), cos(a))
#define COUNT 30.

#define DISTORT .7
#define SQR(x) ((x)*(x))


float tt;

vec2 kalei(vec2 uv) { 
    float n = N;
    float r = TAU/n;

    for(float i=0.; i<n; i++) {     
    	uv = abs(uv);
        uv.x -= .2*i+.2;
    	uv *= rot(r*i-.09*tt);
    }

    uv = abs(uv) - (sin(.15*tt)+1.2);

    return uv;
}


vec3 spiral(vec2 uv, float i) {  
    uv *= rot(i*PI+tt*.3);
    uv += DISTORT*sin(5.*uv.yx);
	return flower(uv)*SQR(hue(i+tt*.2));
}   

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord*2. - iResolution.xy)/iResolution.y;

    uv*=1.5;
       vec3 e1 =spiral(vec2(2.,2.), iTime*0.10);

    vec2 uv0 = uv;
    vec2 uv2 = uv;

    vec2 uvb = uv;

    float tt = iTime*.0;
uv= kalei(uv*5.+e1.xz);
    vec3 col = vec3(0);
    for(float j = 0.; j < N; j++) {

        uv+=e1.xy;
        float stepf = j/N;
        float z =  fract(stepf-.05*(tt+6.*curve(tt+2., 4.))); // depth value

        float luma = smoothstep(0.2, .9, exp(-z*1.5)); // brightness with exponential decay
        luma *= smoothstep(1., .8, exp(-z*1.));

        float  blur = smoothstep(.1, 0.0, z); // depth of field 



        for(float i=0.; i< 5.; i++) {



            vec3 c = pal(2.5*SIN(3.*chebd(uv0, K)-.1*tt-4.*curve(tt, 2.)) + tt*.4 + i*.4+.4*j);

            float d = ((chebd(uv, K)-.5));

            d = abs(d -.4*i);
            d = abs(.1*d+sin(d*8.+tt+j*.3)/8.);

            d =  smoothstep(.015+.11*blur, .0, d);
            col += d*luma*c;

        }
    }


    // Output to screen
    col *= mix(.2, 1., (1.8-pow(dot(uvb, uvb), .4))); // vignette
    fragColor = vec4(col,1.0);
}
